mapper.select:
/* mybatis.mapper.idmapping.getKtIdBySnsTemporaryId : SNS 임시 ID로 전환된 KT ID를 조회한다. */
SELECT USER_ID AS KT_ID
FROM TB_USER_KT
WHERE SNS_TEMP_ID = #{userId}
AND JOIN_STATUS = 'G0001'
LIMIT 1

/* mybatis.mapper.idmapping.checkKtIdExists : KT ID 레코드 존재 여부를 확인한다. */
SELECT COUNT(*)
FROM TB_USER_KT
WHERE USER_ID = #{ktId}

mapper.update:
/* mybatis.mapper.idmapping.migrateUserKtRecord : TB_USER_KT PK 변경 (v3) */
/* Step 1: 새 KT ID로 INSERT (기존 데이터 복사) */ INSERT INTO TB_USER_KT ( USER_ID, MOBILE_NO, EMAIL, GENDER, BIRTH_DAY, PUSH_RCV_YN, MKT_RCV_YN, JOIN_STATUS, MEM_STATUS, OS_TP, DUP_ID, APP_VRSN, MKT_CHG_DT, REG_DT, MOD_DT, NAME, KT_YN, MOBILE_CD, CREDENTIAL_ID, SNS_TEMP_ID, REVIEW_YN, REVIEW_REG_DT, PRF_FLAG, PRF_DT ) SELECT #{newKtId}, /* USER_ID: 새 KT ID */ MOBILE_NO, EMAIL, GENDER, BIRTH_DAY, PUSH_RCV_YN, MKT_RCV_YN, JOIN_STATUS, #{newMemStatus}, OS_TP, DUP_ID, APP_VRSN, MKT_CHG_DT, REG_DT, NOW(), NAME, KT_YN, MOBILE_CD, #{credentialId}, /* CREDENTIAL_ID: IAMUI 발급 */ #{snsTemporaryId}, /* SNS_TEMP_ID: 이전 임시 ID 이력 */ REVIEW_YN, REVIEW_REG_DT, PRF_FLAG, PRF_DT FROM TB_USER_KT WHERE USER_ID = #{oldSnsId};
/* Step 2: 기존 SNS 레코드 삭제 */ DELETE FROM TB_USER_KT WHERE USER_ID = #{oldSnsId}

/* mybatis.mapper.idmapping.updateUserKtId : TB_USER의 KT_ID를 갱신한다. */
UPDATE TB_USER 
SET 
	KT_ID = #{newKtId},
	MOD_DT = NOW()
WHERE CREDENTIAL_ID = #{credentialId}

/* mybatis.mapper.idmapping.migrateUserId : 공용/종속 테이블 USER_ID 일괄 변경 */
UPDATE ${tableName}
SET USER_ID = #{newKtId}
WHERE USER_ID = #{oldSnsId}

/* mybatis.mapper.idmapping.migrateKtIdColumn : KT_ID 컬럼 일괄 변경 */
UPDATE ${tableName}
SET KT_ID = #{newKtId}
WHERE KT_ID = #{oldSnsId}

/* mybatis.mapper.idmapping.migrateRecvUserId : RECV_USER_ID 일괄 변경 */
UPDATE ${tableName}
SET RECV_USER_ID = #{newKtId}
WHERE RECV_USER_ID = #{oldSnsId}

mapper.select:
/* mybatis.mapper.idmapping.getSnsIdByKtId : KT_ID로 이전 SNS_ID를 조회한다. */
SELECT SNS_TEMP_ID
FROM TB_USER_KT
WHERE USER_ID = #{ktId}
AND SNS_TEMP_ID IS NOT NULL
LIMIT 1
